# One frame of the current animation. The BOOT button picks the mode (flow 'mode').
N = 8        # pixels: match the neopixel node's count
B = 48       # brightness cap, 0-255: 8 pixels at full white is a lot for USB power

f = context.get('f', 0) + 1
context.set('f', f)
mode = flow.get('mode', 0)

def wheel(p):
    # Colour wheel 0-255 -> (r, g, b): red -> green -> blue -> red.
    p = p % 256
    if p < 85:
        return (255 - p * 3, p * 3, 0)
    if p < 170:
        p -= 85
        return (0, 255 - p * 3, p * 3)
    p -= 170
    return (p * 3, 0, 255 - p * 3)

def pack(rgb, level):
    # (r, g, b) at level 0-255 of the brightness cap -> 0xRRGGBB
    r, g, b = rgb
    k = B * level // 255
    return ((r * k // 255) << 16) | ((g * k // 255) << 8) | (b * k // 255)

if mode == 0:
    # Rainbow drifting along the strip.
    msg['payload'] = [pack(wheel(f * 3 + i * 256 // N), 255) for i in range(N)]
elif mode == 1:
    # Comet: a bright head with a fading tail, changing colour as it goes.
    head = (f // 2) % N
    colour = wheel(f)
    px = []
    for i in range(N):
        d = (head - i) % N
        px.append(pack(colour, 255 >> (d * 2)) if d < 4 else 0)
    msg['payload'] = px
else:
    # Breathe: the whole strip fades up and down in one slowly changing colour.
    t = f % 100
    level = t * 255 // 50 if t < 50 else (100 - t) * 255 // 50
    msg['payload'] = pack(wheel(f // 4), level)
return msg
